// Pide a THERS el siguiente lote. El BACKEND decide quién lo recibe y con qué números; aquí solo se
// recoge. Llamada firmada con el secreto compartido (HMAC-SHA256 de "<marca>.<cuerpo>").
const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET || '';
const base = ($env.THERS_API_URL || '').replace(/\/$/, '');
if (!secret || !base) throw new Error('Faltan N8N_WEBHOOK_SECRET o THERS_API_URL');

// Cursor y contador de páginas vienen del acuse anterior; el disparador inicial no los trae.
const previous = $input.first() ? $input.first().json : {};
const cursor = previous.next_after || null;
const page = cursor ? (previous.page || 1) + 1 : 1;
if (page > 20) return [];   // tope de seguridad: nunca más de 20 lotes por corrida

const data = await (async () => {
  const ts = Math.floor(Date.now() / 1000);
  const body = JSON.stringify(cursor ? { limit: 50, after: cursor } : { limit: 50 });
  const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.' + body).digest('hex');
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: base + '/internal/automations/weekly-summaries/next',
    headers: {
      'Content-Type': 'application/json',
      'X-THERS-Timestamp': String(ts),
      'X-THERS-Signature': signature,
    },
    body,       // texto EXACTO: la firma cubre estos bytes
    json: false,
  });
  return typeof response === 'string' ? JSON.parse(response) : response;
})();

return data.items.map((item) => ({
  json: { ...item, period: data.period, next_after: data.next_after, page },
}));

// Redacta el resumen de cada persona a partir de los números que dio THERS (solo conteos).
const items = $input.all();
return items.map((item) => {
  const s = item.json;
  const m = s.metrics;
  const lines = [];
  if (m.new_followers) lines.push('- Nuevos seguidores: ' + m.new_followers);
  if (m.likes_received) lines.push('- Me gusta recibidos: ' + m.likes_received);
  if (m.comments_received) lines.push('- Comentarios recibidos: ' + m.comments_received);
  if (m.unread_notifications) lines.push('- Avisos sin leer: ' + m.unread_notifications);
  const name = s.first_name ? ' ' + s.first_name : '';
  const text = 'Hola' + name + ',\n\nAsí te fue en THERS del ' + s.period.from + ' al ' + s.period.to + ':\n\n'
    + lines.join('\n')
    + '\n\nPuedes dejar de recibir este resumen cuando quieras desde Ajustes, en la app.\n\n— THERS';
  return { json: { ...s, mail: { to: s.recipient_email, subject: 'Tu semana en THERS', text } } };
});

// Le dice a THERS qué correos salieron. THERS marca cada resumen como entregado una sola vez, así
// que repetir este flujo no manda dos resúmenes de la misma semana. Un envío fallido se informa como
// "failed": no se marca y volverá a ofrecerse en la próxima corrida.
const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET || '';
const base = ($env.THERS_API_URL || '').replace(/\/$/, '');

const originals = $('Redactar resumen').all();
const results = $input.all();
const ackItems = originals.map((original, index) => {
  const result = results[index] ? results[index].json : {};
  // Resend responde { id: "..." } cuando acepta el correo; cualquier otra cosa es un fallo.
  const sent = Boolean(result && result.id && !result.error);
  return {
    user_id: original.json.user_id,
    idempotency_key: original.json.idempotency_key,
    status: sent ? 'sent' : 'failed',
  };
});

const answer = await (async () => {
  const ts = Math.floor(Date.now() / 1000);
  const body = JSON.stringify({ items: ackItems });
  const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.' + body).digest('hex');
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: base + '/internal/automations/weekly-summaries/ack',
    headers: {
      'Content-Type': 'application/json',
      'X-THERS-Timestamp': String(ts),
      'X-THERS-Signature': signature,
    },
    body,       // texto EXACTO: la firma cubre estos bytes
    json: false,
  });
  return typeof response === 'string' ? JSON.parse(response) : response;
})();

const first = originals[0] ? originals[0].json : {};
return [{ json: { ...answer, next_after: first.next_after || null, page: first.page || 1 } }];
